{
  "title": "数据盗取",
  "scene": "你站在一家名为‘霓虹巨塔’的巨型企业大楼前，大楼外墙上闪烁着五彩斑斓的霓虹灯。你发现有三个入口：正门、侧门和后门。正门有严密的安保，侧门看起来有些老旧，后门则有一群穿着义体增强服的员工进进出出。你的目标是潜入大楼内部，盗取一份关键的数据文件。你注意到，侧门上方有一个监控摄像头，但摄像头的视角似乎有些偏离，这可能是你的机会。",
  "goal": "潜入大楼内部，获取数据文件",
  "clue": "侧门的监控摄像头视角偏离",
  "choices": [
    {
      "id": "A",
      "text": "从正门强行闯入",
      "outcome": "你试图强行闯入正门，但立即被安保人员发现并制服。你被驱逐出大楼，但没有受到严重伤害。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "从侧门潜入",
      "outcome": "你利用侧门上方摄像头视角偏离的机会，小心翼翼地潜入大楼。虽然有些惊险，但你成功进入了大楼内部。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "伪装成员工从后门进入",
      "outcome": "你试图模仿义体增强服的员工，但你的伪装不够逼真，被门口的员工认出并询问。幸运的是，你成功地编造了一个合理的借口，得以进入大楼。",
      "result": "partial",
      "next": "next_level"
    }
  ]
}
